INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_6325660489', 'Dive Seenigama Dive Lanka', 80.0919254, 6.1583507, 'attraction', 'Ancient traditions, Kandy Period', '{"summary":"While ''Dive Seenigama Dive Lanka'' is a modern establishment, its name and location are intrinsically linked to the historically significant Seenigama area. This coastal region is renowned for the ancient Seenigama Devalaya, an island temple dedicated to the guardian deity Dedimunda Deviyo, a site of pilgrimage and unique traditional rituals for centuries.","architectural_details":"The Seenigama Devalaya, the historical heart of the area, is situated on a small rocky island and features traditional Sri Lankan temple architecture. Its shrines, dedicated to Dedimunda Deviyo, typically incorporate white-washed walls and tiled roofs, reflecting styles common in post-Kandy period temple construction, though specific ancient structures have undergone renovations over time.","cultural_significance":"The Seenigama area, through its revered Devalaya, holds profound cultural significance as a center for traditional Sri Lankan spiritual practices, particularly the ''dehi kapima'' (lime cutting) ritual. It symbolizes justice and protection, attracting devotees who seek divine intervention and making it a unique expression of folk religion and cultural identity in Sri Lanka."}', '["Seenigama","Island Temple","Dedimunda Deviyo","Rituals","Folk Religion","Coastal Heritage","Pilgrimage Site","Hikkaduwa Area"]', '{"pronunciation_guide":"See-ni-ga-ma Dee-va Lank-a, De-di-mun-da De-vi-yo, De-hi Ka-pi-ma","key_facts_short":"Modern dive center, Seenigama historical area, island temple, Dedimunda Deviyo, justice rituals"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_4556181993', 'Turtle sanctuary', 80.0884684, 6.1671685, 'attraction', 'Contemporary Conservation', '{"summary":"Sri Lanka''s coastline is a vital nesting ground for several species of sea turtles, leading to the establishment of sanctuaries for their protection. These facilities primarily focus on rescuing injured turtles, rehabilitating them, and operating hatcheries to increase the survival rate of hatchlings before their release into the ocean.","architectural_details":"Simple, functional structures comprising concrete holding tanks, shaded enclosures for hatchlings and injured turtles, and basic visitor information centers. Construction materials are typically local and practical, focusing on utility rather than elaborate design.","cultural_significance":"These sanctuaries play a crucial role in the conservation of endangered sea turtle species native to Sri Lankan waters. They contribute significantly to marine biodiversity protection, environmental education, and sustainable eco-tourism, highlighting Sri Lanka''s commitment to natural heritage."}', '["Wildlife Conservation","Sea Turtles","Eco-tourism","Marine Life","Rehabilitation Center","Hatchery","Environmental Education"]', '{"pronunciation_guide":"Tur-tle Sanc-tu-a-ry","key_facts_short":"Sea turtle conservation, rehabilitation center, eco-tourism, educational site, marine biodiversity"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_6347257887', 'Tsunami Monument', 80.0892894, 6.1665372, 'monument', 'Contemporary (21st Century)', '{"summary":"The Tsunami Monument stands as a solemn memorial to the thousands of lives lost in Sri Lanka during the devastating 2004 Indian Ocean tsunami. It serves as a poignant reminder of the tragedy and a tribute to the resilience of the affected communities.","architectural_details":"Constructed primarily from concrete, the monument often features an abstract, wave-like form, symbolizing the destructive power of the tsunami. Its modern design emphasizes remembrance and reflection rather than traditional Sri Lankan architectural styles.","cultural_significance":"This site holds profound cultural significance as a national symbol of grief, remembrance, and the enduring spirit of the Sri Lankan people in the face of immense natural disaster. It also highlights the global solidarity and aid received during the recovery period."}', '["Tsunami Memorial","2004 Disaster","Remembrance Site","Modern Monument","Coastal Sri Lanka","Natural Disaster","Galle Landmark","Resilience Symbol"]', '{"pronunciation_guide":"Tsoo-nah-mee Mon-yoo-ment","key_facts_short":"Commemorates 2004 tsunami, Located in Galle, Symbol of remembrance, Modern concrete structure, Represents national resilience"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_3377399101', 'Clippenburg Bastion', 80.2140301, 6.0270001, 'archaeological_site', 'Dutch Colonial', '{"summary":"Clippenburg Bastion is a key defensive structure of the historic Galle Fort, built by the Dutch during their colonial rule in the 17th century. Strategically positioned, it guarded the northern approach to the harbor, protecting the vital port from naval attacks. It stands as a testament to the extensive fortifications that secured Dutch interests in Ceylon.","architectural_details":"Constructed primarily from coral, granite, and laterite, bound with lime mortar, the bastion exemplifies 17th-century European military engineering. Its robust, angular form with thick walls and gun emplacements was designed to withstand cannon fire and provide commanding views over the harbor entrance.","cultural_significance":"As an integral part of the UNESCO World Heritage-listed Galle Fort, Clippenburg Bastion represents a significant period of Sri Lanka''s colonial past and its strategic importance in maritime trade. It showcases the enduring architectural legacy of European powers and contributes to the fort''s global recognition as a well-preserved fortified city."}', '["Galle Fort","Dutch Colonial","Bastion","Fortification","Archaeological Site","Maritime History","UNESCO Heritage","17th Century"]', '{"pronunciation_guide":"Clip-pen-burg Bas-tion","key_facts_short":"Dutch colonial, Galle Fort, 17th century, defensive structure, UNESCO site"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_11502316371', 'Elephant riding', 80.1728791, 6.0901532, 'attraction', 'Ancient to Modern Era', '{"summary":"Elephants have held a revered position in Sri Lankan history for millennia, serving in royal processions, warfare, and heavy labor. While their traditional roles have evolved, elephant riding has emerged as a contemporary tourist attraction, offering visitors a unique interaction with these majestic animals.","architectural_details":"The activity of elephant riding does not involve permanent architectural structures. Historically, temporary platforms or simple wooden howdahs were crafted from timber and textiles for carrying riders, designed for function rather than architectural style.","cultural_significance":"Elephants are deeply embedded in Sri Lankan culture, symbolizing strength, wisdom, and prosperity. They play a vital role in religious festivals, particularly the Esala Perahera, and represent a living link to the island''s rich heritage and natural biodiversity."}', '["Elephant experience","Wildlife interaction","Cultural heritage","Sri Lankan elephants","Tourism attraction","Historical practice","Animal encounter"]', '{"pronunciation_guide":"El-uh-fuhnt Ry-ding","key_facts_short":"Historical elephant use, Cultural significance, Modern tourism attraction"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_4556165692', 'Wijala beach', 80.2636381, 5.9996808, 'attraction', 'Contemporary', '{"summary":"Wijaya Beach is a renowned sandy stretch on Sri Lanka''s southern coast, celebrated for its calm, shallow waters protected by a natural offshore reef. While lacking ancient historical structures, its natural beauty has made it a significant contemporary attraction for both local communities and international tourists. It offers a tranquil environment ideal for swimming and relaxation.","architectural_details":"As a natural coastal formation, Wijaya Beach features no historical architectural structures. Its defining characteristics are its crescent-shaped sandy shore, the natural coral reef that creates a sheltered lagoon, and the surrounding tropical vegetation.","cultural_significance":"Wijaya Beach holds contemporary cultural significance as a prominent leisure destination, contributing substantially to the local tourism economy. It embodies Sri Lanka''s appeal as a tropical paradise, serving as a gathering place for families and a key highlight for visitors seeking pristine natural beauty and safe ocean activities."}', '["Beach","Southern Coast","Tourism","Swimming","Reef","Relaxation","Family-friendly","Natural beauty"]', '{"pronunciation_guide":"Wi-ja-ya Beach","key_facts_short":"Southern coast, Calm waters, Natural reef, Popular tourist spot, Family-friendly"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_5800272353', 'Pallisters', 80.3953023, 5.9862051, 'attraction', 'British Colonial', '{"summary":"Pallisters likely refers to a colonial-era bungalow or estate residence, characteristic of the British presence in Sri Lanka''s Southern Province. These buildings served as homes for European planters or administrators, reflecting the social hierarchy and economic activities of the colonial period.","architectural_details":"Typically constructed with plastered brick or stone walls and timber roofs with clay tiles, these bungalows feature wide verandas, high ceilings, and large windows designed for tropical ventilation. The style often blends European architectural influences like Neoclassical or Victorian with adaptations for the local climate.","cultural_significance":"Such colonial bungalows are significant as tangible reminders of Sri Lanka''s British colonial past, showcasing the architectural legacy and lifestyle of the era. They represent a distinct period of social and economic transformation, contributing to the island''s diverse heritage landscape."}', '["British Colonial","Historic Residence","Colonial Architecture","Galle Heritage","Tropical Bungalow","Architectural Landmark","Planter''s Home"]', '{"pronunciation_guide":"Pal-lis-ters","key_facts_short":"British Colonial, historic residence, architectural heritage, Galle region, tropical design"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_5242116921', 'Turtle Bay', 80.4655387, 5.9412891, 'attraction', 'Natural Heritage', '{"summary":"Turtle Bay is a natural coastal area, likely named for its historical or ongoing significance as a habitat for sea turtles. While not an archaeological site, its ecological importance contributes significantly to Sri Lanka''s natural heritage and biodiversity.","architectural_details":"Not applicable, as Turtle Bay is a natural coastal feature defined by its sandy shores, rock formations, and marine environment, rather than man-made structures.","cultural_significance":"Its significance lies in its role as a potential nesting or feeding ground for various species of sea turtles, which are culturally revered and protected in Sri Lanka. It contributes to the nation''s rich biodiversity and eco-tourism appeal, drawing attention to marine conservation efforts."}', '["Natural landmark","Coastal","Sea turtles","Biodiversity","Marine life","Eco-tourism","Southern coast"]', '{"pronunciation_guide":"Tur-tle Bay","key_facts_short":"Natural bay, sea turtle habitat, biodiversity, southern Sri Lanka"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_9722122604', 'Hemachandra Gunasekara', 80.4295665, 5.9738344, 'memorial', 'Post-Independence Sri Lanka', '{"summary":"This memorial honors Hemachandra Gunasekara, a figure whose contributions are remembered within the local community. While specific national records are limited, such memorials typically commemorate individuals for their service, sacrifice, or significant impact on local life. It serves as a focal point for community remembrance and historical reflection.","architectural_details":"Often constructed from durable materials like concrete, granite, or marble, these memorials typically feature a commemorative plaque or a bust. The style is generally functional and reverent, reflecting contemporary Sri Lankan memorial design.","cultural_significance":"Memorials like this are vital for preserving local history and identity, fostering community cohesion, and ensuring that significant individuals are not forgotten. They serve as sites for local ceremonies, reinforcing shared values and heritage within the region."}', '["Local memorial","Community heritage","Remembrance site","Sri Lankan history","Post-independence era","Public monument"]', '{"pronunciation_guide":"He-ma-chan-dra Gu-na-se-ka-ra","key_facts_short":"Local memorial, honors Hemachandra Gunasekara, community remembrance, post-independence"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_9722124151', 'General Montagu Jayawickrama', 80.429318, 5.9738297, 'memorial', 'Post-Independence Sri Lanka (20th Century)', '{"summary":"This memorial honors Montagu Jayawickrama (1911-2001), a prominent Sri Lankan politician and public servant. He held significant ministerial portfolios, including Justice and Public Administration, and served as Governor of the North Western Province. The memorial commemorates his extensive contributions to national governance and regional development.","architectural_details":"Typically, memorials for such figures are constructed from durable materials like stone or concrete, often featuring a sculpted bust or an inscribed plaque detailing the individual''s achievements and dates. These monuments are usually placed in public areas, designed for accessibility and public remembrance.","cultural_significance":"Montagu Jayawickrama was a key figure in Sri Lankan politics during the mid to late 20th century, representing the Weligama electorate for many years. His memorial signifies the nation''s recognition of his dedication to public service, his role in shaping post-independence governance, and his impact on the local community."}', '["Politician","Public Servant","Post-Independence","Sri Lankan History","Memorial","Matara District","Weligama","Governor"]', '{"pronunciation_guide":"Mon-ta-gu Ja-ya-wick-ra-ma","key_facts_short":"Sri Lankan politician, Minister of Justice, Governor, Weligama representative, Public service"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_4620115989', 'Tea factory Hill garden', 80.2204598, 6.1556042, 'attraction', 'British Colonial', '{"summary":"Tea factories like Hill Garden emerged during the British Colonial era, playing a pivotal role in processing Ceylon''s burgeoning tea industry. These establishments transformed freshly picked tea leaves into the finished product, driving the island''s economic landscape and global reputation for tea.","architectural_details":"Typically constructed with durable materials such as brick, concrete, and timber, these multi-story industrial buildings often feature large windows for ventilation and corrugated iron roofs. Their functional design facilitates the gravity-fed tea processing stages, from wilting to drying.","cultural_significance":"Tea factories are central to Sri Lanka''s identity as a premier tea producer, symbolizing the nation''s agricultural heritage and economic backbone. They represent the legacy of colonial enterprise and the enduring global impact of ''Ceylon Tea'', a key export and cultural identifier."}', '["Tea industry","Colonial heritage","Agricultural landmark","Sri Lankan tea","Processing plant","Historic factory","Hill country","Economic history"]', '{"pronunciation_guide":"Tea fac-to-ry Hill Gar-den","key_facts_short":"British Colonial era, tea processing, economic backbone, Ceylon Tea heritage"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_4621586590', 'Tea shop-factory', 80.3242, 6.1950683, 'attraction', 'British Colonial / Post-Colonial', '{"summary":"Tea factories emerged in Ceylon during the British Colonial era, transforming the island''s economy and landscape. These establishments were crucial for processing tea leaves, from wilting to drying and grading, for global export. Many continue to operate, blending historical methods with modern practices.","architectural_details":"Typically constructed with robust materials like brick, timber, and corrugated iron, these factories feature multi-level structures designed for gravity-fed processing. Large windows and open spaces facilitate ventilation and light, characteristic of functional industrial architecture of the period.","cultural_significance":"Tea factories are vital symbols of Sri Lanka''s economic backbone and colonial heritage, representing the island''s global prominence in the tea industry. They embody the legacy of plantation agriculture and the enduring cultural significance of Ceylon Tea."}', '["Tea Industry","Colonial Heritage","Sri Lankan Tea","Industrial Architecture","Economic History","Plantation Economy","Tea Processing"]', '{"pronunciation_guide":"Tee shop-fak-tuh-ree","key_facts_short":"Tea processing, colonial legacy, economic backbone, industrial heritage, Ceylon Tea"}');
INSERT INTO heritage_locations (id, name, longitude, latitude, category, era, deep_history, tags, tts_hints) VALUES ('lk_osm_node_6273572085', 'Paid Palm Rope Swing', 80.2600697, 6.0013739, 'attraction', 'Contemporary Sri Lanka', '{"summary":"This attraction is a contemporary feature, popular with tourists seeking recreational activities along Sri Lanka''s scenic coastlines. It represents a modern adaptation of traditional leisure, offering visitors a unique photo opportunity and experience. Its emergence is tied to the growth of coastal tourism in recent decades.","architectural_details":"Constructed primarily from natural materials such as sturdy palm trees and durable ropes, often with a simple wooden seat. Its structural form is rudimentary, designed for temporary recreational use rather than permanent architectural significance, emphasizing safety and simplicity.","cultural_significance":"While not a site of ancient heritage, the palm rope swing reflects a contemporary aspect of Sri Lankan tourism, blending local natural resources with recreational demand. It symbolizes the evolving landscape of leisure activities offered to visitors, contributing to the local tourism economy and providing unique photo opportunities."}', '["Tourist attraction","Recreational","Coastal activity","Photo spot","Modern leisure","Palm tree swing","Beach experience","Contemporary tourism"]', '{"pronunciation_guide":"Payd Palm Rohp Swing","key_facts_short":"Modern tourist attraction, recreational activity, popular photo spot, uses natural materials, contributes to local tourism"}');

